import { useState } from "react";

function Contador() {
  const [n, setN] = useState(0);
  return <button onClick={() => setN((prev) => prev + 1)}>Clics: {n}</button>;
}

function Reloj() {
  const [hora, setHora] = useState(new Date());
  useEffect(() => {
    const id = setInterval(() => setHora(new Date()), 1000);
    return () => clearInterval(id); // limpieza al desmontar
  }, []); // [] = solo al montar
  return <p>{hora.toLocaleTimeString("es-PE")}</p>;
}

function Usuarios() {
  const [usuarios, setUsuarios] = useState([]);
  useEffect(() => {
    let activo = true;
    fetch("/api/usuarios").then((r) => r.json()).then((d) => activo && setUsuarios(d));
    return () => { activo = false; }; // ignora respuestas viejas
  }, []);
  return <ul>{usuarios.map((u) => <li key={u.id}>{u.nombre}</li>)}</ul>;
}

function Buscador() {
  const inputRef = useRef(null);
  const enfocar = () => inputRef.current.focus();
  return <><input ref={inputRef} /><button onClick={enfocar}>Ir al buscador</button></>;
}

function Lista({ productos, filtro }) {
  const visibles = useMemo(
    () => productos.filter((p) => p.nombre.includes(filtro)),
    [productos, filtro]
  );
  return <ul>{visibles.map((p) => <li key={p.id}>{p.nombre}</li>)}</ul>;
}

const Boton = memo(({ onClick }) => <button onClick={onClick}>Limpiar</button>);

function Buscador() {
  const [texto, setTexto] = useState("");
  const limpiar = useCallback(() => setTexto(""), []); // Boton no se re-renderiza al escribir
  return <><input value={texto} onChange={(e) => setTexto(e.target.value)} /><Boton onClick={limpiar} /></>;
}

const TemaContext = createContext("claro");

function App() {
  return <TemaContext value="oscuro"><Boton /></TemaContext>;
}
function Boton() {
  const tema = useContext(TemaContext); // "oscuro"
  return <button className={tema}>OK</button>;
}

function reducer(estado, accion) {
  if (accion.type === "sumar") return { ...estado, n: estado.n + 1 };
  if (accion.type === "reiniciar") return { ...estado, n: 0 };
  return estado;
}
function Contador() {
  const [estado, dispatch] = useReducer(reducer, { n: 0 });
  return <button onClick={() => dispatch({ type: "sumar" })}>{estado.n}</button>;
}

function Tarjeta({ titulo, color = "gris", children }) {
  return (
    <div className={`tarjeta ${color}`}>
      <h2>{titulo}</h2>
      {children}
    </div>
  );
}
// uso: <Tarjeta titulo="Hola"><p>Contenido</p></Tarjeta>

function Panel({ cargando, items }) {
  if (cargando) return <p>Cargando...</p>; // return temprano
  return (
    <div>
      {items.length === 0 ? <p>Sin resultados</p> : <Lista items={items} />}
      {items.length > 0 && <small>{items.length} resultados</small>}
    </div>
  );
}

function Saludo() {
  const saludar = (nombre) => alert(`Hola, ${nombre}`);
  const escribir = (e) => console.log(e.target.value); // en cada tecla
  return <><button onClick={() => saludar("Ana")}>Saludar</button><input onChange={escribir} /></>;
}

function Formulario() {
  const [email, setEmail] = useState("");
  const enviar = (e) => { e.preventDefault(); console.log(email); };
  return (
    <form onSubmit={enviar}>
      <input value={email} onChange={(e) => setEmail(e.target.value)} />
      <button disabled={!email.includes("@")}>Enviar</button>
    </form>);
}

function Saludo({ nombre }) {
  return <h1>Hola, {nombre}</h1>;
}

export default function App() {
  return <><Saludo nombre="Ana" /><Saludo nombre="Luis" /></>;
}

function useLocalStorage(clave, inicial) {
  const [valor, setValor] = useState(
    () => JSON.parse(localStorage.getItem(clave)) ?? inicial
  );
  useEffect(() => localStorage.setItem(clave, JSON.stringify(valor)), [clave, valor]);
  return [valor, setValor];
}
